// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depAmt, uint256 minSum, uint256 colAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmt);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: depAmt}() {} catch { return; }
        vm.assume(c.balances(address(this)) >= minSum);
        vm.assume(colAmt < c.balances(address(this)));
        try c.Collect(colAmt) {} catch { return; }
        assertTrue(c.balances(address(this)) == depAmt - colAmt);
    }

    function testFuzz_run(uint256 depAmt, uint256 minSum, uint256 colAmt) public {
        _run(depAmt, minSum, colAmt);
    }

    receive() external payable {}
}
